"""Binary searches on an ascending list that may hold duplicates."""


def _bisect_left(items, value):
    """Smallest index i such that items[i] >= value (or len(items))."""
    low, high = 0, len(items)
    while low < high:
        middle = (low + high) // 2
        if items[middle] < value:
            low = middle + 1
        else:
            high = middle
    return low


def _bisect_right(items, value):
    """Smallest index i such that items[i] > value (or len(items))."""
    low, high = 0, len(items)
    while low < high:
        middle = (low + high) // 2
        if items[middle] <= value:
            low = middle + 1
        else:
            high = middle
    return low


def find_first(items, value):
    index = _bisect_left(items, value)
    if index < len(items) and items[index] == value:
        return index
    return -1


def find_last(items, value):
    index = _bisect_right(items, value) - 1
    if index >= 0 and items[index] == value:
        return index
    return -1


def count_of(items, value):
    return _bisect_right(items, value) - _bisect_left(items, value)


def insert_position(items, value):
    return _bisect_right(items, value)
